    refused.pump_to_completion(refused_id);
    const ToolActivity& not_saved = *refused.coordinator.find(refused_id);
    CHECK(not_saved.state == ToolState::Failed);
    REQUIRE(not_saved.error.has_value());
    CHECK(not_saved.error->code == "local_save_failed");
    // The save's own reason, not only that it failed.
    CHECK(not_saved.error->message.find("(disk full)") != std::string::npos);
    CHECK(refused.object_count() == 1);

    Harness unsaved;
    unsaved.coordinator.set_version_callbacks(
        [](const ToolActivity&) { return std::string("v-before"); },
        [](const ToolActivity&, const std::string&) { throw std::runtime_error("disk full"); });
    const std::string unsaved_id = unsaved.coordinator.submit(unsaved.duplicate_cube_request(), "version-after-refused").action_id;
    unsaved.pump_to_completion(unsaved_id);
    const ToolActivity& made = *unsaved.coordinator.find(unsaved_id);
    REQUIRE(made.error.has_value());
    CHECK(made.error->code == "local_save_failed");
    CHECK(made.error->message.find("(disk full)") != std::string::npos);
    CHECK(unsaved.object_count() == 2);
}

